<div class="section-list" data-page-builder data-reorder-url="<?= site_url('admin/pages/' . $page['id'] . '/sections/reorder') ?>" data-csrf-name="<?= csrf_token() ?>" data-csrf-hash="<?= csrf_hash() ?>">
<?php foreach ($sections as $section): ?>
